const cleanTerminalSetup=setup;setup=function(id,w){cleanTerminalSetup(id,w);if(id!=='terminal')return;const welcome=w.querySelector('.term-welcome'),cat=w.querySelector('.term-cat');w.querySelector('.term-eyebrow').textContent='PAPEL SHELL / TU ESPACIO DE COMANDOS';w.querySelector('.term-welcome h2').textContent='Terminal';w.querySelector('.term-welcome p').textContent='Crea, organiza y abre tus herramientas.';w.querySelector('.term-quick [data-termcmd="cat"]').remove();const timer=setTimeout(()=>{cat.remove();welcome.classList.add('greeting-finished')},2200);const cleanup=extraCleanup.get(w);extraCleanup.set(w,()=>{clearTimeout(timer);cleanup?.()})};
